mapper.select:
SELECT pp.id, ppd.id AS changeDetailId, pp.code, pp.create_user_id AS createUserId, pp.create_user_name AS createUserName, pp.create_time AS createTime, ppd.supplier_id AS supplierId, (SELECT name FROM supplier WHERE id=ppd.supplier_id) AS supplierName, ppd.sku_id AS skuId, ppd.sku_no AS skuNo, ppd.product_name AS productName,ppd.min_qty AS minQty,ppd.max_qty AS maxQty, pp.approve_status AS approveStatus, ppd.tax_price AS taxPrice, ppd.currency, ppd.tax_rate*100 AS taxRate , ppd.effective_date AS effectiveDate, pp.purchase_org_id AS purchaseOrgId, pp.purchase_org_name AS purchaseOrgName, ppd.disabled, ppd.purchase_price_detail_id as purchasePriceDetailId, ppd.remark as detailRemark, pp.approve_time FROM purchase_price_change_detail ppd INNER JOIN purchase_price_change pp ON ppd.purchase_price_change_id=PP.id WHERE ${params.sqlMap.default} and pp.is_deleted = false AND ppd.is_deleted= false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pp.create_time DESC,ppd.id DESC

SELECT pp.id, ppd.id AS changeDetailId, ppd.purchase_price_detail_id, pp.code, pp.create_user_id AS createUserId, pp.create_user_name AS createUserName, pp.create_time AS createTime, ppd.supplier_id, (SELECT name FROM supplier WHERE id=ppd.supplier_id) AS supplierName, ppd.sku_id, ppd.sku_no, ppd.product_name,ppd.min_qty,ppd.max_qty, pp.approve_status, ppd.tax_price, ppd.currency, ppd.tax_rate*100 AS taxRate , ppd.effective_date, pp.purchase_org_id, pp.purchase_org_name, ppd.disabled, ppd.remark as detailRemark, pp.approve_time FROM purchase_price_change_detail ppd INNER JOIN purchase_price_change pp ON ppd.purchase_price_change_id = pp.id WHERE ${params.sqlMap.default} and pp.is_deleted = false AND ppd.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pp.create_time DESC,ppd.id DESC

select count(distinct pp.id) from purchase_price_change pp left join purchase_price_change_detail ppd on pp.id = ppd.purchase_price_change_id and ppd.is_deleted = false
${params.sqlMap.default} and pp.is_deleted = false
${params.permissionSql}
